d": "UV", "provider": "Natural Inks", "lot": "26106584", "entry_date": "2026-10-08", "shelf_days": 185, "cost_kg": 601.6, "grams": 4224}, {"name": "P361", "code": "0361CA02", "kind": "Base Agua", "provider": "Natural Inks", "lot": "26096358", "entry_date": "2026-10-07", "shelf_days": 365, "cost_kg": 244.4, "grams": 4152}, {"name": "Naranja 021", "code": "UVF-3122", "kind": "UV", "provider": "Natural Inks", "lot": "25116673", "entry_date": "2026-10-07", "shelf_days": 185, "cost_kg": 601.6, "grams": 4160}]'::jsonb) loop
  select pl.* into item from public.prisma_lots pl join public.prisma_products pp on pp.id=pl.product_id where pp.code=r->>'code' and pl.lot=r->>'lot';
  if not found then raise exception 'No se encontró el lote % del inventario.',r->>'lot';end if;
  difference:=(r->>'grams')::numeric-item.grams;
  update public.prisma_lots set grams=(r->>'grams')::numeric,cost_kg=(r->>'cost_kg')::numeric where id=item.id;
  if difference<>0 then insert into public.prisma_movements(lot_id,type,grams,cost_kg,date,reason) values(item.id,case when difference>0 then 'in' else 'out' end,abs(difference),(r->>'cost_kg')::numeric,public.prisma_today(),'Actualización de existencias · PDF invee.pdf');end if;
 end loop;
 insert into public.prisma_metadata values('inventory_pdf_corrected_v1','1');
 end if;
end $inventory_update$;
